const s = (title, formula, ...paragraphs) => ({ title, formula, paragraphs })
const e = (title, problem, steps, answer) => ({ title, problem, steps, answer })
const q = (text, options, answer, explanation) => ({ text, options, answer, explanation })
const entries = []
function add(id, title, subject, goal, sections, examples, mistakes, challenges) {
  entries.push({ id, title, subject, intro: goal, chemistryLesson: { goal, sections, examples, mistakes, challenges }, practice: challenges.map(item => [item.text, item.options[item.answer], ...item.options.filter((_, i) => i !== item.answer), item.explanation]) })
}
add('tipos-de-oxidos', 'Tipos de óxidos', 'Química',
  'Reconhecer óxidos, calcular números de oxidação e relacionar sua classificação às reações, à nomenclatura e aos impactos ambientais.', [
  s('1. O que caracteriza um óxido?', 'Óxido: composto binário em que o oxigênio é o elemento mais eletronegativo.', 'Binário significa formado por dois elementos químicos, não por dois átomos. CO₂, CaO e Fe₂O₃ são óxidos. NaOH não é óxido: contém três elementos e pertence às bases. Em OF₂, o flúor é mais eletronegativo que o oxigênio; por isso, trata-se de fluoreto de oxigênio.', 'Nos óxidos usuais, o NOX do O é −2. Como a soma dos NOX de um composto neutro é zero, em Fe₂O₃ temos 2x + 3(−2) = 0, portanto Fe é +3. Peróxidos e superóxidos são casos especiais, estudados adiante.'),
  s('2. Óxidos básicos e óxidos ácidos', 'CaO + 2 HCl → CaCl₂ + H₂O · CO₂ + 2 NaOH → Na₂CO₃ + H₂O', 'Óxidos básicos reagem com ácidos formando sal e água. São comuns entre metais de baixo NOX, como Na₂O e CaO. Alguns reagem com água e formam bases: CaO + H₂O → Ca(OH)₂. Não generalize: CuO é básico, mas não reage apreciavelmente com água para formar uma solução de hidróxido.', 'Óxidos ácidos reagem com bases formando sal e água. Muitos são de ametais, como CO₂, SO₂ e SO₃; também existem óxidos ácidos de metais em NOX alto, como CrO₃. SO₃ + H₂O → H₂SO₄ ilustra formação de ácido. A classificação depende do comportamento químico, não apenas de ser metal ou ametal.'),
  s('3. Anfóteros e neutros', 'ZnO + 2 HCl → ZnCl₂ + H₂O · ZnO + 2 OH⁻ + H₂O → [Zn(OH)₄]²⁻', 'Óxidos anfóteros podem reagir tanto com ácidos como com bases fortes, nas condições adequadas. ZnO e Al₂O₃ são exemplos importantes. A segunda equação mostra a formação de um complexo em solução aquosa básica; livros também podem representar zincatos em outras condições.', 'Óxidos neutros, como CO, NO e N₂O, não apresentam o comportamento ácido ou básico usual frente à água, aos ácidos e às bases. Neutro não significa inerte: CO pode queimar formando CO₂ e NO pode oxidar-se a NO₂. Tampouco significa ausência de efeitos biológicos ou ambientais.'),
  s('4. Peróxidos, superóxidos e óxidos mistos', 'Peróxido: O₂²⁻, NOX médio −1 · superóxido: O₂⁻, NOX médio −½.', 'H₂O₂ e Na₂O₂ são peróxidos e contêm ligação O–O. Em 2 H₂O₂ → 2 H₂O + O₂, o mesmo elemento sofre redução e oxidação. KO₂ é um superóxido. Não use automaticamente O = −2 nesses compostos: reconheça primeiro o grupo presente.', 'Óxidos mistos podem ser descritos como combinação de óxidos do mesmo elemento em diferentes NOX. A magnetita, Fe₃O₄, pode ser representada como FeO·Fe₂O₃, reunindo Fe(II) e Fe(III). O NOX médio +8/3 não significa que cada átomo de ferro tenha essa carga.'),
  s('5. Como nomear sem decorar listas', 'FeO: óxido de ferro(II) · Fe₂O₃: óxido de ferro(III) · CO₂: dióxido de carbono.', 'Na nomenclatura de Stock, indique em algarismos romanos o NOX do elemento quando necessário. Na₂O é óxido de sódio; o sódio tem usualmente NOX +1. Prefixos mono-, di- e tri- indicam quantidades de átomos e são frequentes em compostos moleculares: monóxido de carbono e trióxido de enxofre.', 'Separe três tarefas: identificar os elementos, calcular NOX e investigar o comportamento ácido-base. O nome permite identificar a composição, mas não substitui a análise das reações. CO e CO₂, por exemplo, têm classificações e efeitos diferentes.'),
  s('6. Óxidos no ambiente e nas provas', 'SO₂ e NOₓ → transformações atmosféricas → ácidos e deposição ácida.', 'A combustão de combustíveis com enxofre pode liberar SO₂. Óxidos de nitrogênio formados em combustões também participam da deposição ácida. Esses gases sofrem reações na atmosfera; não se trata apenas de um gás dissolvendo instantaneamente na chuva. A água de chuva natural já pode ser levemente ácida pela presença de CO₂.', 'CO é tóxico por comprometer o transporte de oxigênio no sangue. CO₂ participa do efeito estufa e do equilíbrio dos carbonatos; não confunda seus efeitos com os do CO. Nas questões, relacione o óxido à fonte, à transformação química e à consequência ambiental.'),
], [e('Classificação e reação', 'Como classificar CaO e CO₂ e prever a reação entre eles?', ['CaO reage com ácidos: é básico. CO₂ reage com bases: é ácido.', 'Um óxido básico e um ácido podem formar sal.', 'Conserve Ca, C e O: CaO + CO₂ → CaCO₃.'], 'Forma-se carbonato de cálcio.'), e('Encontrar o NOX', 'Qual é o NOX do manganês em Mn₂O₇?', ['O vale −2: sete O somam −14.', 'O composto é neutro: 2x − 14 = 0.', 'Logo x = +7; esse óxido apresenta caráter ácido.'], 'Mn tem NOX +7.')],
['Não classifique todo óxido metálico como básico.', 'Não confunda neutro com inerte.', 'Confira peróxidos antes de atribuir NOX −2 ao oxigênio.'], [q('Qual óxido é anfótero?', ['ZnO', 'CO', 'Na₂O'], 0, 'ZnO reage tanto com ácidos como com bases fortes.'), q('Em H₂O₂, o NOX do oxigênio é:', ['−2', '−1', '+1'], 1, 'O peróxido tem grupo O₂²⁻; cada O tem NOX −1.'), q('Qual é um óxido ácido?', ['CaO', 'CO₂', 'CO'], 1, 'CO₂ reage com bases; CaO é básico e CO é neutro.'), q('Fe₂O₃ é chamado de:', ['Óxido de ferro(III)', 'Óxido de ferro(II)', 'Peróxido de ferro'], 0, '2x + 3(−2) = 0 resulta em x = +3.')])

add('separacao-de-misturas', 'Separação de misturas', 'Química',
'Escolher métodos de separação pelas propriedades dos componentes e planejar sequências para misturas homogêneas e heterogêneas.', [
s('1. Componentes, fases e propriedades', 'Componente é uma substância; fase é uma região com aspecto e propriedades uniformes.', 'Água e sal dissolvido formam uma fase e dois componentes. Água líquida e gelo formam duas fases e um componente. Uma mistura homogênea apresenta uma fase; uma heterogênea, duas ou mais. O aspecto depende também da escala: coloides podem parecer homogêneos a olho nu.', 'Separar uma mistura envolve explorar diferenças de tamanho, densidade, solubilidade, volatilidade, magnetismo ou afinidade por materiais. Antes de escolher o equipamento, pergunte: quais são os componentes, quais fases existem e qual produto quero recuperar?'),
s('2. Misturas de sólidos', 'Peneiração: tamanho · imantação: resposta magnética · dissolução fracionada: solubilidade.', 'Peneiração separa partículas de tamanhos diferentes; catação usa diferenças visíveis e coleta manual. Imantação pode retirar limalha de ferro de areia, mas não separa qualquer metal: alumínio e cobre não se comportam como o ferro nesse processo.', 'Na dissolução fracionada, um solvente dissolve preferencialmente um componente. Para sal e areia, adicione água, filtre a areia e depois recupere o sal por cristalização ou evaporação. Levigação usa arraste por corrente de líquido; ventilação, por gás. Flotação explora a associação de partículas a bolhas ou diferenças de comportamento na superfície.'),
s('3. Sólido em líquido: filtrar ou decantar?', 'Filtração retém partículas; não retém, em geral, íons dissolvidos.', 'Na filtração, o sólido insolúvel fica como resíduo e o líquido atravessa o filtro como filtrado. Água com areia pode ser filtrada; água com sal dissolvido não perde o sal num filtro de papel comum. Escolher a porosidade adequada faz parte do método.', 'Decantação permite que partículas sedimentem por ação da gravidade antes de separar o líquido. Centrifugação acelera a separação de componentes com diferentes comportamentos de sedimentação. Ela não substitui universalmente a filtração nem remove automaticamente solutos moleculares dissolvidos.'),
s('4. Líquidos imiscíveis e extração', 'Funil de separação: líquidos imiscíveis com densidades diferentes.', 'Água e óleo formam camadas. No funil, escoa-se primeiro a camada inferior, mais densa nas condições observadas. Não presuma que todo solvente orgânico fique em cima: alguns são mais densos que água. A diferença de densidade organiza as camadas; a imiscibilidade permite que permaneçam distintas.', 'Extração por solvente transfere um soluto para uma fase em que ele tem maior afinidade. Em uma extração líquido-líquido, usam-se líquidos pouco miscíveis e depois separa-se cada camada. A escolha considera solubilidade, seletividade e condições da substância, evitando confundir extração com reação química.'),
s('5. Soluções: evaporação, cristalização e destilação', 'Destilação simples: vaporizar e condensar · fracionada: sucessivas etapas de vaporização e condensação.', 'Evaporar a água de uma solução salina recupera o sal, mas não recolhe a água. Na destilação simples, o vapor é condensado, permitindo recuperar o solvente de um soluto pouco volátil. Cristalização pode usar resfriamento ou evaporação controlada para formar cristais, explorando a solubilidade e deixando parte das impurezas na solução.', 'Destilação fracionada separa componentes voláteis com diferentes volatilidades usando uma coluna. O vapor tende a ser enriquecido no componente mais volátil. Não se obtém sempre pureza absoluta: misturas azeotrópicas limitam a separação por destilação comum. O petróleo é separado em frações, que ainda são misturas.'),
s('6. Métodos especiais e leitura de experimentos', 'Cromatografia: distribuição entre fase móvel e fase estacionária.', 'Na cromatografia, componentes migram de modos diferentes por suas interações com as fases. Uma tinta pode revelar vários pigmentos no papel. Maior solubilidade na fase móvel pode favorecer migração, mas a interação com a fase estacionária também precisa ser considerada.', 'Sublimação é útil quando um sólido passa ao vapor e pode ser recuperado sem que os demais acompanhem significativamente. Liquefação e destilação fracionada separam gases do ar após resfriamento. Em provas, justifique cada etapa pela propriedade explorada e indique onde ficou cada componente.'),
], [e('Água, sal, areia e ferro', 'Como recuperar os quatro componentes?', ['Use um ímã para retirar o ferro.', 'Filtre a areia; o sal dissolvido acompanha a água.', 'Destile o filtrado: recolha água no condensador e sal no recipiente.'], 'Imantação → filtração → destilação simples.'), e('Escolher o método', 'Por que filtrar água salgada não produz água sem sal?', ['O sal está dissociado em íons dispersos na solução.', 'Esses íons passam pelos poros de um filtro de papel comum.', 'Uma opção para recuperar água é vaporizar e condensar o solvente.'], 'Filtração comum não separa soluto dissolvido.')],
['Não confunda número de fases com número de componentes.', 'Não use filtração comum para retirar sal dissolvido.', 'Escolha evaporação ou destilação conforme queira recuperar também o solvente.'], [q('Água e óleo podem ser separados por:', ['Funil de separação', 'Peneiração', 'Imantação'], 0, 'São líquidos imiscíveis que formam camadas.'), q('Que propriedade fundamenta a peneiração?', ['Temperatura de ebulição', 'Tamanho das partículas', 'NOX'], 1, 'Os poros deixam passar partículas menores e retêm as maiores.'), q('Para recuperar a água de uma solução de NaCl, usa-se:', ['Filtração em papel', 'Destilação simples', 'Catação'], 1, 'A água vaporiza e é recolhida após condensação; o sal pouco volátil permanece.'), q('A cromatografia depende:', ['Das interações com as fases móvel e estacionária', 'Somente da massa total', 'Da formação obrigatória de novas substâncias'], 0, 'A distribuição diferenciada entre as fases produz separação.')])

add('reacoes-quimicas', 'Reações químicas', 'Química',
'Interpretar equações, balancear átomos e cargas, reconhecer tipos de reação e compreender energia, velocidade e reversibilidade.', [
s('1. Transformação física ou química?', 'Reagentes → produtos · (s) sólido · (l) líquido · (g) gás · (aq) solução aquosa.', 'Em uma reação química, átomos são reorganizados e formam substâncias diferentes. Derreter gelo mantém H₂O: é uma transformação física. Queimar hidrogênio forma água: é uma transformação química. Uma solução pode ter reações ocorrendo, mas dissolver uma substância não deve ser automaticamente chamado de reação.', 'Formação de gás, precipitado, mudança de cor e liberação de calor são indícios, não provas isoladas. Ebulição produz bolhas sem formar outra substância. Analise a identidade das espécies e as condições indicadas, incluindo aquecimento, catalisador e luz.'),
s('2. Balanceamento e conservação', 'CH₄ + 2 O₂ → CO₂ + 2 H₂O', 'Balancear é igualar a quantidade de átomos de cada elemento nos dois lados. Comece pelos elementos presentes em menos espécies e deixe H e O para o final quando isso simplificar. Ajuste coeficientes, nunca índices da fórmula. Depois confira todos os elementos.', 'Na combustão do metano, um C exige um CO₂; quatro H exigem duas águas; há então quatro O nos produtos, exigindo dois O₂. Em equações iônicas, conserve também a carga. A massa se conserva em sistema fechado; em recipiente aberto, gases podem entrar ou sair.'),
s('3. Síntese, decomposição e deslocamento', 'Síntese: A + B → AB · decomposição: AB → A + B · deslocamento: A + BC → AC + B.', 'Síntese reúne reagentes em um produto, como 2 Mg + O₂ → 2 MgO. Decomposição parte de um reagente e forma mais de um produto: CaCO₃ → CaO + CO₂, sob aquecimento. Essas classificações descrevem o formato da equação e podem coexistir com outras, como oxirredução.', 'No deslocamento simples, um elemento substitui outro: Zn + CuSO₄ → ZnSO₄ + Cu. A ocorrência depende da reatividade e das condições; não basta encaixar símbolos. Um metal menos reativo não desloca espontaneamente qualquer outro de uma solução.'),
s('4. Dupla troca, precipitação e neutralização', 'Ag⁺(aq) + Cl⁻(aq) → AgCl(s) · H₃O⁺ + OH⁻ → 2 H₂O.', 'Na dupla troca, há reorganização entre espécies de dois compostos. Em solução, uma transformação pode ser favorecida pela formação de precipitado, gás ou espécie pouco ionizada. AgNO₃ + NaCl → AgCl + NaNO₃ produz AgCl insolúvel; Na⁺ e NO₃⁻ permanecem como íons espectadores.', 'A neutralização entre ácido e base pode formar sal e água: HCl + NaOH → NaCl + H₂O. Considere a quantidade de H⁺ e OH⁻ disponível: H₂SO₄ pode exigir dois mol de NaOH por mol para neutralização total. Misturar soluções não garante que o pH final seja 7, especialmente com excesso ou espécies fracas.'),
s('5. Oxidação, redução e combustão', 'Oxidação: aumento do NOX · redução: diminuição do NOX.', 'Na reação Zn + Cu²⁺ → Zn²⁺ + Cu, Zn perde elétrons e é oxidado; Cu²⁺ recebe elétrons e é reduzido. O agente redutor é quem doa elétrons e se oxida; o oxidante recebe e se reduz. Não confunda agente com o processo que ele provoca no outro.', 'Combustão é uma reação de oxirredução com um oxidante. Na combustão completa de hidrocarboneto com oxigênio suficiente, formam-se CO₂ e H₂O. Na incompleta, podem aparecer CO e carbono sólido. Neutralização e precipitação não são obrigatoriamente oxirreduções: confira se houve mudança de NOX.'),
s('6. Energia, velocidade e equilíbrio', 'Exotérmica: ΔH < 0 · endotérmica: ΔH > 0 · catalisador reduz a barreira de ativação.', 'Romper ligações exige energia; formar ligações libera energia. O balanço determina se a reação libera ou absorve calor. Temperatura, concentração, superfície de contato e catalisador podem alterar a velocidade, mas não devem ser confundidos com o sinal de ΔH.', 'Uma seta dupla indica reversibilidade. No equilíbrio dinâmico, as velocidades direta e inversa são iguais; concentrações ficam constantes, não necessariamente iguais. Catalisadores aceleram a aproximação do equilíbrio sem mudar sua constante a uma dada temperatura e sem alterar ΔH.'),
], [e('Balancear a formação de amônia', 'Balanceie N₂ + H₂ → NH₃.', ['Dois N no reagente exigem 2 NH₃.', 'Agora há seis H no produto, exigindo 3 H₂.', 'Confira: N = 2 e H = 6 nos dois lados.'], 'N₂ + 3 H₂ → 2 NH₃.'), e('Identificar o agente redutor', 'Em Mg + 2 H⁺ → Mg²⁺ + H₂, quem é o redutor?', ['Mg muda de NOX 0 para +2: perde dois elétrons.', 'H muda de +1 para 0: recebe elétrons.', 'Quem se oxida reduz a outra espécie.'], 'Mg é o agente redutor.')],
['Não altere índices para balancear.', 'Não confunda agente oxidante com espécie oxidada.', 'Não conclua que qualquer bolha prova reação química.'], [q('Qual equação está balanceada?', ['2 H₂ + O₂ → 2 H₂O', 'H₂ + O₂ → H₂O', 'H₂ + 2 O₂ → H₂O'], 0, 'Há quatro H e dois O em cada lado.'), q('Quem recebe elétrons sofre:', ['Oxidação', 'Redução', 'Sublimação'], 1, 'Receber elétrons diminui o NOX.'), q('A formação de AgCl sólido em solução é:', ['Precipitação', 'Destilação', 'Fusão'], 0, 'Íons dissolvidos formam um sólido pouco solúvel.'), q('Um catalisador em uma reação reversível:', ['Altera a constante de equilíbrio', 'Acelera a chegada ao equilíbrio sem alterar a constante', 'Muda obrigatoriamente ΔH'], 1, 'Ele modifica o caminho reacional, não o equilíbrio termodinâmico.')])

add('hidretos', 'Hidretos', 'Química',
'Compreender o hidrogênio em compostos binários, distinguir hidretos iônicos, covalentes e metálicos e prever NOX e reações típicas.', [
s('1. Hidrogênio e a classificação dos compostos', 'H com metal eletropositivo: frequentemente −1 · H com ametal mais eletronegativo: geralmente +1.', 'O hidrogênio tem um elétron e pode participar de ligações de formas diferentes. Hidretos são compostos do hidrogênio com outro elemento, classificados conforme a ligação e a estrutura. A nomenclatura escolar pode usar o termo em sentido amplo para compostos binários ou restringi-lo aos casos com H negativo; observe a convenção do enunciado.', 'Em NaH, o sódio é +1 e o H é −1. Em HCl, Cl é −1 e H é +1; HCl é tratado como haleto de hidrogênio e, em água, como ácido clorídrico. Calcule NOX pela eletronegatividade e pelo balanço de cargas, não pela ordem de escrita.'),
s('2. Hidretos iônicos ou salinos', 'NaH: Na⁺H⁻ · CaH₂: Ca²⁺ e 2 H⁻.', 'Metais muito eletropositivos, especialmente alcalinos e alguns alcalinoterrosos, formam hidretos com caráter iônico. O ânion H⁻ possui dois elétrons. NaH é hidreto de sódio; CaH₂ é hidreto de cálcio. A neutralidade elétrica determina a proporção entre cátion e hidreto.', 'Esses sólidos não devem ser confundidos com soluções aquosas de H⁻. O íon hidreto é uma base muito forte e reage com água. BeH₂ e outros compostos não seguem simplesmente o modelo iônico dos metais do grupo; posição na tabela é uma pista, não uma regra sem exceções.'),
s('3. Reação com água e formação de hidrogênio', 'NaH + H₂O → NaOH + H₂ · CaH₂ + 2 H₂O → Ca(OH)₂ + 2 H₂.', 'No modelo iônico, H⁻ recebe um próton da água e forma H₂. Os H do gás têm NOX zero; o H do hidreto sobe de −1 a 0 e um H da água desce de +1 a 0. Há, portanto, uma transformação ácido-base acompanhada de mudança de NOX.', 'A proporção é fundamental: um mol de NaH forma um mol de H₂; um mol de CaH₂ forma dois mol. Essas reações podem liberar muito calor e gás inflamável, sendo estudadas por equações e problemas teóricos, sem manipulação doméstica.'),
s('4. Hidretos covalentes', 'CH₄: metano · NH₃: amônia · SiH₄: silano.', 'Com elementos do bloco p, o hidrogênio geralmente forma ligações covalentes. Muitos desses compostos são moleculares, mas existem estruturas mais complexas, como as de hidretos de boro e alguns hidretos poliméricos. Não atribua a todos as propriedades de um sal.', 'O NOX do H depende do parceiro: em CH₄ e NH₃ é +1, pois C e N são mais eletronegativos. Em SiH₄, H é mais eletronegativo que Si e tem NOX −1. Polaridade molecular depende também da geometria: CH₄ tem ligações distribuídas simetricamente e é apolar.'),
s('5. Hidretos metálicos e armazenamento', 'Hidreto metálico: hidrogênio incorporado à estrutura de um metal ou de uma liga.', 'Muitos metais de transição e ligas incorporam hidrogênio em posições da rede cristalina. A composição pode variar e não ser expressa por uma razão inteira fixa. Algumas dessas fases mantêm propriedades metálicas e não se descrevem adequadamente como moléculas isoladas.', 'Materiais capazes de absorver e liberar hidrogênio são estudados em armazenamento e baterias. A aplicação depende de temperatura, pressão, reversibilidade, massa e estabilidade do material. Ter hidrogênio na fórmula não significa que ele possa ser liberado facilmente em qualquer condição.'),
s('6. Fórmula, NOX e estequiometria nas provas', 'Massa molar de CaH₂ ≈ 40 + 2 × 1 = 42 g/mol.', 'Resolva na ordem: identifique o parceiro do H, estabeleça o tipo de composto, calcule o NOX e escreva a equação balanceada. Para cálculos, converta massa em mol e use os coeficientes. Não transforme o índice 2 de CaH₂ diretamente em uma proporção entre gramas.', 'Diferencie H⁻ (hidreto), H⁺ (representação simplificada de próton em reações) e H₂ (substância simples). Em solução aquosa, prótons estão solvatados, frequentemente representados por H₃O⁺. São espécies com cargas, estruturas e reatividades diferentes.'),
], [e('Prever a fórmula', 'Qual é a fórmula do hidreto iônico de cálcio?', ['O cátion cálcio é Ca²⁺.', 'Cada H⁻ compensa uma carga positiva.', 'São necessários dois hidretos por cálcio.'], 'CaH₂.'), e('Calcular gás produzido', 'Quantos mol de H₂ podem resultar de 21 g de CaH₂ puro com água em excesso?', ['M(CaH₂) = 42 g/mol; n = 21/42 = 0,5 mol.', 'A equação forma 2 mol de H₂ por mol de CaH₂.', '0,5 × 2 = 1 mol.'], '1 mol de H₂, com reação completa.')],
['Não atribua sempre NOX +1 ao H.', 'Não confunda H⁻, H⁺ e H₂.', 'Não trate todo hidreto como sólido iônico.'], [q('Em NaH, o NOX do H é:', ['−1', '+1', '0'], 0, 'Na é +1 e o composto é neutro.'), q('CaH₂ com água em excesso forma:', ['Ca(OH)₂ e H₂', 'Somente Ca e O₂', 'CaCO₃ e CO₂'], 0, 'CaH₂ + 2 H₂O → Ca(OH)₂ + 2 H₂.'), q('Um exemplo de hidreto covalente molecular é:', ['NaH', 'CH₄', 'CaH₂'], 1, 'O metano apresenta ligações covalentes.'), q('Em SiH₄, o NOX do H é:', ['+1', '−1', '+4'], 1, 'H é mais eletronegativo que Si; Si é +4 e cada H é −1.')])

add('calculos-quimicos', 'Cálculos químicos', 'Química',
'Dominar massa atômica, mol, fórmulas, gases, concentrações e proporções reacionais com análise de unidades e exemplos completos.', [
s('1. Massa atômica, molecular e molar', 'M(H₂SO₄) = 2 × 1 + 32 + 4 × 16 = 98 g/mol.', 'Massa atômica relativa compara a massa de um átomo a uma referência baseada no carbono-12. A massa de um átomo pode ser expressa em u; a massa molar é a massa por quantidade de matéria, usualmente em g/mol. Seus valores numéricos se correspondem nas aproximações escolares, mas são grandezas diferentes.', 'Some os valores de todos os átomos da fórmula, multiplicando índices e parênteses. Em Al₂(SO₄)₃, há 2 Al, 3 S e 12 O. Com Al = 27, S = 32 e O = 16, M = 54 + 96 + 192 = 342 g/mol. Para compostos iônicos, fale em unidades de fórmula, não em moléculas isoladas.'),
s('2. Mol e número de partículas', 'n = m/M · N = nNₐ · Nₐ = 6,02214076 × 10²³ mol⁻¹.', 'O mol conta entidades especificadas: átomos, moléculas, íons ou unidades de fórmula. Para converter gramas em mol, divida pela massa molar; para obter entidades, multiplique pelo número de Avogadro. Uma amostra de 18 g de água, usando M = 18 g/mol, tem 1 mol de moléculas.', 'Cada molécula de H₂O contém três átomos. Portanto, 1 mol de água contém 2 mol de átomos de H e 1 mol de átomos de O, ou 3 mol de átomos no total. Um mol de NaCl idealmente dissociado contém 1 mol de Na⁺ e 1 mol de Cl⁻; deixe claro o que está sendo contado.'),
s('3. Composição percentual e fórmulas', '% de um elemento = massa desse elemento na fórmula / massa molar × 100.', 'Em H₂O, H contribui com 2 g a cada 18 g: 11,1% em massa. O contribui com 16/18 × 100 ≈ 88,9%. Fórmula mínima ou empírica é a menor razão inteira entre átomos; fórmula molecular indica a quantidade real em uma molécula.', 'Para obter fórmula mínima a partir de percentuais, suponha 100 g, converta cada massa em mol, divida pelo menor valor e ajuste para inteiros. Se aparecer 1,5, multiplique todas as razões por 2. A massa molar permite encontrar quantas vezes a fórmula mínima cabe na molecular.'),
s('4. Volume dos gases e temperatura', 'PV = nRT · T(K) = temperatura(°C) + 273,15.', 'Use uma constante R compatível com as unidades de pressão e volume. Com R ≈ 0,082 L·atm·mol⁻¹·K⁻¹, use L, atm e K. O modelo de gás ideal é uma aproximação; a prova deve indicar as condições ou permitir essa hipótese.', 'O volume molar não é sempre 22,4 L/mol. Esse valor aproximado corresponde a 0 °C e 1 atm no modelo ideal. A 1 bar, ou em outra temperatura, o volume muda. Para gases nas mesmas T e P, volumes são proporcionais aos mols.'),
s('5. Concentração e diluição', 'C = m/V (g/L) · c = n/V (mol/L) · c₁V₁ = c₂V₂.', 'Concentração em massa usa massa de soluto e volume final de solução. Concentração molar usa mols de soluto e volume final. Dividir C pela massa molar dá c quando as unidades são compatíveis. Já densidade usa massa total da solução, não apenas a do soluto.', 'Na diluição sem perda ou reação, a quantidade de soluto permanece constante. Se 100 mL de solução 2 mol/L são diluídos até 500 mL, c₂ = 2 × 100/500 = 0,4 mol/L. Foram acrescentados aproximadamente 400 mL de água se os volumes forem tratados como aditivos; o dado central é o volume final.'),
s('6. Da equação à quantidade pedida', 'Dado → mol → proporção dos coeficientes → mol do produto → unidade final.', 'Balanceie primeiro. Em N₂ + 3 H₂ → 2 NH₃, 1 mol de N₂ produz 2 mol de NH₃, se houver H₂ suficiente. Se ambos os reagentes forem dados, compare n/coefficientes: a menor razão indica o limitante. Não compare diretamente as massas disponíveis.', 'Pureza reduz a massa efetivamente reagente: massa pura = massa da amostra × fração de pureza. Rendimento compara produto real ao teórico: η = real/teórico × 100. Aplique fatores em etapas e confira unidades. Se uma massa molar está em g/mol, primeiro converta kg em g.'),
s('7. Estratégia e conferência do resultado', 'Escreva unidades em cada etapa e verifique a ordem de grandeza.', 'Organize uma linha com o dado e outra com o pedido. Anote hipóteses: pureza, excesso, conversão completa, temperatura e pressão. Use fatores de conversão que cancelem as unidades antigas. Arredonde ao final para evitar acumular erro.', 'Um rendimento de 150% exige revisar o cálculo ou reconhecer impureza/umidade no produto medido; não é produção acima do máximo previsto para um produto puro. Uma concentração após diluição deve diminuir. Esses testes simples ajudam a detectar erros antes de marcar a resposta.'),
], [e('Encontrar a fórmula molecular', 'Uma substância tem 40,0% C, 6,7% H e 53,3% O; M = 180 g/mol. Use C = 12, H = 1 e O = 16.', ['Em 100 g: C = 40/12 ≈ 3,33 mol; H = 6,7 mol; O = 53,3/16 ≈ 3,33 mol.', 'Divida por 3,33: razão aproximada 1:2:1, fórmula mínima CH₂O.', 'M(CH₂O) = 30 g/mol; 180/30 = 6. Multiplique todos os índices por 6.'], 'C₆H₁₂O₆.'), e('Pureza e rendimento', '100 g de calcário com 80% de CaCO₃ produzem quanto CO₂ com rendimento de 75%? M(CaCO₃) = 100; M(CO₂) = 44 g/mol.', ['Massa pura = 100 × 0,80 = 80 g; n = 0,8 mol.', 'CaCO₃ → CaO + CO₂: razão 1:1, logo 0,8 mol de CO₂.', 'Massa teórica = 0,8 × 44 = 35,2 g; massa obtida = 35,2 × 0,75.'], '26,4 g de CO₂.')],
['Não confunda mol com massa ou número de átomos.', 'Não use 22,4 L/mol fora das condições correspondentes.', 'Não aplique coeficientes diretamente a massas em gramas.'], [q('36 g de H₂O, com M = 18 g/mol, correspondem a:', ['2 mol de moléculas', '36 mol', '18 mol'], 0, 'n = 36/18 = 2 mol.'), q('Quantos átomos estão representados em uma unidade de fórmula de Al₂(SO₄)₃?', ['9', '17', '7'], 1, 'São 2 Al + 3 S + 12 O = 17 átomos na unidade de fórmula; o composto é iônico.'), q('Uma solução 1 mol/L diluída de 100 para 400 mL fica com:', ['4 mol/L', '0,25 mol/L', '1 mol/L'], 1, 'c₂ = 1 × 100/400 = 0,25 mol/L.'), q('Uma amostra de 50 g a 80% de pureza contém:', ['40 g de substância pura', '10 g de substância pura', '62,5 g de substância pura'], 0, '50 × 0,80 = 40 g; as impurezas representam 10 g.')])

add('fermentacao', 'Fermentação', 'Biologia',
'Entender como a fermentação mantém a glicólise, comparar suas modalidades e relacionar o processo à alimentação e ao metabolismo celular.', [
s('1. ATP, glicose e necessidade de regeneração', 'Glicólise: glicose → 2 piruvatos + saldo de 2 ATP + 2 NADH.', 'ATP transfere energia para processos celulares. A glicólise quebra a glicose no citosol em dez etapas, investe 2 ATP e produz 4 ATP, com saldo de 2. Parte da energia dos elétrons é transferida ao NAD⁺, que se transforma em NADH. Essa via não utiliza oxigênio diretamente.', 'A célula dispõe de uma quantidade limitada de NAD⁺. Se todo ele ficar como NADH, faltará a forma oxidada para a glicólise continuar. A fermentação resolve esse problema transferindo elétrons do NADH para uma molécula orgânica e regenerando NAD⁺. O principal ganho é manter a via funcionando.'),
s('2. O que diferencia fermentação de respiração?', 'Na fermentação, não há cadeia respiratória responsável pela produção de ATP.', 'Nas fermentações lática e alcoólica, o ATP líquido provém da glicólise por fosforilação em nível de substrato. As etapas que regeneram NAD⁺ não acrescentam ATP a esse saldo. A oxidação da glicose é parcial: os produtos ainda conservam bastante energia química.', 'Fermentação não é sinônimo de respiração anaeróbia. Na respiração anaeróbia existe cadeia transportadora de elétrons, mas o aceptor final não é O₂; pode ser nitrato, por exemplo. Na fermentação, o aceptor é uma molécula orgânica derivada do próprio metabolismo, sem esse funcionamento de cadeia respiratória.'),
s('3. Fermentação lática', 'Piruvato + NADH + H⁺ → lactato + NAD⁺.', 'A lactato desidrogenase transfere elétrons para o piruvato, formando lactato. Não há liberação de CO₂ nessa etapa. O processo ocorre em bactérias usadas em alimentos e em células animais. Nas condições fisiológicas, a forma predominante é lactato, embora a expressão “ácido lático” apareça em materiais escolares.', 'Hemácias humanas maduras não têm mitocôndrias e dependem da glicólise, regenerando NAD⁺ pela formação de lactato. Músculos também podem aumentar essa produção quando a demanda energética é elevada. Lactato pode ser utilizado por outros tecidos e convertido em glicose no fígado; não é apenas um resíduo inútil.'),
s('4. Fermentação alcoólica', 'Glicose → 2 etanóis + 2 CO₂ · saldo líquido usual: 2 ATP pela glicólise.', 'Em leveduras, o piruvato perde CO₂ e forma acetaldeído. Depois, o acetaldeído recebe elétrons do NADH e é reduzido a etanol, regenerando NAD⁺. Diferentemente da fermentação lática, há liberação de gás carbônico.', 'Na massa do pão, o CO₂ forma bolhas retidas na estrutura e ajuda a massa a crescer; parte do etanol evapora ao assar. Em bebidas, a produção de etanol é central. Leveduras podem respirar ou fermentar conforme espécie e condições; a presença de oxigênio não impede universalmente toda fermentação.'),
s('5. Alimentos, ambiente e condições do processo', 'Temperatura, disponibilidade de substrato e pH influenciam a atividade dos microrganismos.', 'Bactérias láticas acidificam o leite e contribuem para a textura do iogurte pela alteração das proteínas. A fermentação não significa que qualquer alimento deteriorado seja seguro: processos alimentares dependem de culturas adequadas e controle de condições. O papel biológico deve ser distinguido de recomendações de preparo.', 'A fabricação de vinagre é tradicionalmente chamada de fermentação acética, mas a oxidação do etanol por bactérias acéticas envolve respiração aeróbia. Esse é um exemplo de diferença entre o uso industrial de um nome e a definição bioquímica estrita de fermentação.'),
s('6. Balanço e erros de interpretação', '1 glicose → saldo de 2 ATP nas fermentações lática e alcoólica usuais.', 'A glicólise produz quatro ATP brutos, mas dois foram consumidos; por isso, o saldo é dois. Não some novamente ATP às etapas de formação de lactato ou etanol. A função do NADH é transportar elétrons; a regeneração de NAD⁺ permite continuidade, não cria energia do nada.', 'A dor muscular tardia não é explicada por lactato acumulado durante vários dias. Ela se relaciona a danos microscópicos e respostas inflamatórias após esforço. Em provas, observe local celular, produtos, CO₂, necessidade de regenerar NAD⁺ e diferença entre saldo bruto e líquido.'),
], [e('Comparar duas vias', 'Uma cultura transforma glicose em etanol e libera gás. Qual via é compatível?', ['Etanol aponta para fermentação alcoólica.', 'O gás liberado na conversão de piruvato em acetaldeído é CO₂.', 'O ATP líquido vem da glicólise e o NAD⁺ é regenerado na redução do acetaldeído.'], 'Fermentação alcoólica, com saldo usual de 2 ATP por glicose.'), e('Calcular o saldo', 'Qual o saldo de ATP para 5 moléculas de glicose fermentadas pela via lática?', ['Cada glicose dá saldo de 2 ATP na glicólise.', 'A formação de lactato não acrescenta ATP nesse balanço.', '5 × 2 = 10.'], 'Saldo de 10 moléculas de ATP.')],
['Não confunda fermentação com respiração anaeróbia.', 'Não conte os quatro ATP brutos como saldo.', 'Não atribua dor muscular tardia ao lactato retido.'], [q('A principal função da etapa fermentativa após a glicólise é:', ['Regenerar NAD⁺', 'Produzir oxigênio', 'Formar uma mitocôndria'], 0, 'O NAD⁺ regenerado permite que a glicólise continue.'), q('Qual fermentação libera CO₂ na via usual?', ['Lática', 'Alcoólica', 'Ambas obrigatoriamente'], 1, 'O piruvato perde CO₂ ao formar acetaldeído na via alcoólica.'), q('A glicólise ocorre:', ['No citosol', 'No núcleo', 'Dentro do lisossomo'], 0, 'A glicólise é uma via citosólica.'), q('O saldo usual de ATP por glicose na fermentação lática é:', ['4', '2', '30'], 1, 'São produzidos 4 ATP e consumidos 2 na glicólise: saldo 2.')])

add('respiracao-celular', 'Respiração celular', 'Biologia',
'Acompanhar o caminho da glicose aos produtos finais e entender glicólise, ciclo de Krebs, cadeia respiratória e síntese de ATP.', [
s('1. Visão geral: oxidação e energia', 'C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O + energia transferida e calor.', 'Na respiração aeróbia, compostos orgânicos são oxidados e o O₂ é o aceptor final de elétrons. A energia é liberada em etapas controladas, com parte conservada em ATP. A equação global resume muitas reações e não significa que glicose e oxigênio se encontrem em uma única etapa.', 'Eucariontes realizam glicólise no citosol e as etapas posteriores principalmente nas mitocôndrias. Plantas também respiram, de dia e de noite. Procariontes não têm mitocôndrias, mas muitos respiram utilizando componentes da membrana plasmática.'),
s('2. Glicólise: o início no citosol', 'Por glicose: 2 piruvatos + 2 ATP líquidos + 2 NADH.', 'Uma glicose de seis carbonos origina dois piruvatos de três carbonos. A via investe 2 ATP e gera 4, com saldo de 2 por fosforilação em nível de substrato. Dois NAD⁺ recebem elétrons e formam NADH.', 'A glicólise não consome O₂ diretamente. Sua continuidade, porém, exige regeneração de NAD⁺: isso pode ocorrer associado à respiração ou pela fermentação. Portanto, dizer que glicólise não usa oxigênio não implica que toda a respiração aeróbia seja independente dele.'),
s('3. Oxidação do piruvato e ciclo de Krebs', 'Por glicose: 2 acetil-CoA na etapa de ligação; 2 voltas no ciclo de Krebs.', 'Na matriz mitocondrial, cada piruvato perde CO₂ e origina acetil-CoA, com formação de NADH. Para dois piruvatos, são 2 CO₂ e 2 NADH. O grupo acetil de dois carbonos entra no ciclo ao se combinar com oxaloacetato; esse composto é regenerado ao final.', 'Por glicose, o ciclo gera 4 CO₂, 6 NADH, 2 FADH₂ e 2 GTP ou ATP equivalentes. Somando a oxidação dos piruvatos, os seis carbonos da glicose são liberados como CO₂. A maior parte da energia capturada até aqui está nos transportadores reduzidos, não no pequeno saldo direto de ATP.'),
s('4. Cadeia transportadora e gradiente de prótons', 'Elétrons → cadeia respiratória → bombeamento de H⁺ → gradiente eletroquímico.', 'NADH e FADH₂ entregam elétrons à cadeia na membrana interna da mitocôndria. A transferência libera energia usada por complexos específicos para bombear H⁺ da matriz ao espaço intermembranar. Nem todo complexo bombeia prótons; o complexo II, ligado à entrada de elétrons do FADH₂, não o faz.', 'O O₂ recebe elétrons no final da cadeia e participa da formação de água. Sem esse aceptor, a cadeia aeróbia para, transportadores permanecem reduzidos e outras etapas ficam comprometidas. O oxigênio não é convertido em CO₂: os carbonos do CO₂ vieram dos compostos orgânicos.'),
s('5. ATP sintase e rendimento', 'Quimiosmose: retorno de H⁺ pela ATP sintase acoplado a ADP + Pi → ATP.', 'A membrana interna separa compartimentos e mantém o gradiente. Quando prótons retornam pela ATP sintase, sua energia impulsiona a síntese de ATP. Cadeia respiratória e ATP sintase atuam de forma acoplada; o conjunto é chamado de fosforilação oxidativa.', 'Estimativas didáticas modernas frequentemente indicam cerca de 30–32 ATP por glicose em eucariontes, variando conforme transporte dos elétrons citosólicos, custos e condições celulares. Não trate 36 ou 38 como valores universais. Se a questão fornecer um balanço específico, use as hipóteses informadas.'),
s('6. Integração metabólica e situações de prova', 'Gorduras e aminoácidos também podem alimentar o metabolismo respiratório.', 'Ácidos graxos podem ser degradados por beta-oxidação, gerando acetil-CoA e transportadores reduzidos. Aminoácidos têm destinos variados após processamento de seus grupos nitrogenados. Respiração não é uma via exclusiva da glicose, embora ela seja um modelo útil para estudar o balanço.', 'Um inibidor da cadeia impede o fluxo de elétrons; um desacoplador dissipa o gradiente sem produzir ATP proporcionalmente, favorecendo liberação de calor. São efeitos diferentes. Compare sempre consumo de O₂, gradiente e ATP, evitando memorizar que qualquer alteração produz o mesmo resultado.'),
], [e('Contar carbonos', 'De onde vêm os 6 CO₂ liberados por glicose?', ['Os dois piruvatos liberam 2 CO₂ ao formar acetil-CoA.', 'As duas voltas do ciclo liberam mais 4 CO₂.', '2 + 4 = 6; a glicólise não libera CO₂.'], '2 CO₂ na oxidação do piruvato e 4 no ciclo.'), e('Interpretar falta de O₂', 'Por que a ausência de O₂ compromete a produção mitocondrial de ATP?', ['O₂ é o aceptor final da cadeia aeróbia.', 'Sem ele, a transferência de elétrons e o bombeamento ficam comprometidos.', 'Sem manutenção do gradiente, cai a fosforilação oxidativa.'], 'O problema se propaga da cadeia ao gradiente e à ATP sintase.')],
['Não coloque a glicólise dentro da mitocôndria.', 'Não confunda o papel de O₂ com a origem do carbono do CO₂.', 'Não memorize um rendimento universal de ATP.'], [q('O aceptor final de elétrons da respiração aeróbia é:', ['O₂', 'CO₂', 'Glicose'], 0, 'O₂ recebe elétrons no fim da cadeia e participa da formação de água.'), q('O ciclo de Krebs eucariótico ocorre principalmente:', ['No citosol', 'Na matriz mitocondrial', 'No núcleo'], 1, 'A matriz abriga as enzimas do ciclo, com exceção da succinato desidrogenase na membrana interna.'), q('A maior parcela do ATP da respiração aeróbia é obtida por:', ['Fosforilação oxidativa', 'Fermentação lática', 'Fotólise da água'], 0, 'O gradiente gerado pela cadeia alimenta a ATP sintase.'), q('Por glicose, a glicólise produz saldo de:', ['2 ATP', '4 ATP líquidos', '6 CO₂'], 0, 'Quatro ATP são formados, dois consumidos, e não há CO₂ nessa etapa.')])

add('fotossintese', 'Fotossíntese', 'Biologia',
'Compreender a transformação de energia luminosa em energia química e integrar pigmentos, fase fotoquímica, ciclo de Calvin e fatores ambientais.', [
s('1. O que a fotossíntese realiza?', '6 CO₂ + 6 H₂O + luz → C₆H₁₂O₆ + 6 O₂ (equação global simplificada).', 'Organismos fotossintetizantes usam luz para sustentar a síntese de compostos orgânicos. Plantas, algas e cianobactérias realizam fotossíntese oxigênica. A energia não é criada: é transformada e parte se conserva em ligações químicas. O carbono orgânico vem do CO₂, não dos sais minerais do solo.', 'Na fotossíntese oxigênica, o O₂ liberado se origina da água. Uma representação que explicita água consumida e formada é 6 CO₂ + 12 H₂O → C₆H₁₂O₆ + 6 O₂ + 6 H₂O. Ambas são balanços globais; o açúcar de seis carbonos não surge diretamente em uma única reação.'),
s('2. Cloroplasto e pigmentos', 'Tilacoides: fase fotoquímica · estroma: ciclo de Calvin.', 'Cloroplastos apresentam envelope de duas membranas e um sistema interno de tilacoides, cujo espaço interno é o lúmen. O estroma é a matriz ao redor dessas membranas. As clorofilas e outros pigmentos se associam a proteínas na membrana tilacoidal, formando complexos de captação e conversão da luz.', 'Pigmentos absorvem certas faixas de comprimento de onda e refletem ou transmitem outras. Clorofilas absorvem bastante nas faixas azul e vermelha; a aparência verde resulta da luz relativamente menos absorvida. Carotenoides ampliam a captação e contribuem para proteção contra excesso de luz.'),
s('3. Fluxo de elétrons e fotólise da água', 'Fluxo linear: H₂O → fotossistema II → cadeia → fotossistema I → NADP⁺.', 'No fotossistema II, a energia luminosa permite iniciar um fluxo de elétrons; a oxidação da água repõe elétrons e libera O₂ e H⁺. A passagem pela cadeia contribui para acumular prótons no lúmen. O nome II não indica que ele atue depois do I: a numeração reflete a história de descoberta.', 'No fotossistema I, outra absorção de luz eleva a energia dos elétrons, que podem reduzir NADP⁺ a NADPH. O retorno de prótons do lúmen ao estroma pela ATP sintase permite fotofosforilação. O fluxo linear produz ATP, NADPH e O₂; o fluxo cíclico associado ao fotossistema I contribui para ATP sem produzir NADPH ou O₂ diretamente.'),
s('4. Ciclo de Calvin e produção de carboidratos', '3 CO₂ + 9 ATP + 6 NADPH → saldo de 1 G3P de três carbonos, com regeneração de RuBP.', 'No estroma, a rubisco catalisa a fixação de CO₂ na ribulose-1,5-bisfosfato (RuBP). Após a formação de compostos de três carbonos, ATP e NADPH permitem a redução que origina trioses-fosfato, como G3P. A maior parte é usada para regenerar RuBP, mantendo o ciclo.', 'O saldo de G3P pode contribuir para síntese de glicose, sacarose, amido e outras moléculas. Para um equivalente de seis carbonos, são necessários 6 CO₂, 18 ATP e 12 NADPH no balanço do ciclo. A chamada “fase escura” não exige escuridão: depende dos produtos da fase luminosa e de regulação associada à luz.'),
s('5. Fatores limitantes e ponto de compensação', 'Fotossíntese líquida = fotossíntese bruta − respiração.', 'Intensidade luminosa, concentração de CO₂, temperatura e água podem limitar a taxa. Aumentar luz não produz crescimento ilimitado: a curva pode saturar e excesso de luz pode causar dano. A temperatura afeta enzimas e fechamento estomático; não há uma temperatura ótima universal para todas as espécies.', 'No ponto de compensação luminoso, as trocas de CO₂ da fotossíntese e respiração se equilibram e o saldo líquido é zero. A planta continua realizando os dois processos. Acima desse ponto, pode haver incorporação líquida de carbono; abaixo, o consumo respiratório supera a fixação.'),
s('6. Fotorrespiração e adaptações C₄ e CAM', 'C₄: separação espacial · CAM: separação temporal da fixação inicial e do ciclo de Calvin.', 'A rubisco pode atuar com O₂, iniciando fotorrespiração, que consome recursos e libera parte do carbono fixado sem o mesmo benefício de síntese de açúcar. Condições quentes e secas podem favorecer esse problema quando o fechamento dos estômatos reduz a entrada de CO₂.', 'Plantas C₄ concentram CO₂ junto à rubisco por etapas em células diferentes, tipicamente mesófilo e bainha vascular. Plantas CAM captam CO₂ principalmente à noite e o armazenam em ácidos orgânicos para utilização de dia. Essas adaptações têm custos e vantagens dependentes do ambiente; não tornam uma via superior em toda situação.'),
], [e('Rastrear o oxigênio', 'Uma planta recebe água com oxigênio marcado. Onde pode aparecer a marca liberada na fase luminosa?', ['A água é oxidada no fotossistema II.', 'Esse processo libera O₂.', 'Logo o gás oxigênio pode conter a marca da água.'], 'No O₂ liberado, evidenciando sua origem na água.'), e('Ler a troca gasosa', 'Uma folha fixa 12 unidades de CO₂ pela fotossíntese e libera 4 pela respiração no mesmo intervalo. Qual o saldo?', ['Identifique as taxas brutas no mesmo intervalo.', 'Calcule fotossíntese líquida: 12 − 4.', 'Saldo positivo indica incorporação líquida.'], '8 unidades de CO₂ incorporadas.')],
['Não diga que o O₂ liberado vem do CO₂.', 'Não interprete fase escura como uma etapa exclusiva da noite.', 'Não esqueça que plantas também respiram.'], [q('O O₂ liberado na fotossíntese oxigênica vem:', ['Da água', 'Do CO₂', 'Da glicose do solo'], 0, 'A oxidação da água no fotossistema II fornece elétrons e libera O₂.'), q('O ciclo de Calvin ocorre:', ['No lúmen', 'No estroma', 'Na matriz mitocondrial'], 1, 'O estroma contém a maquinaria de fixação de carbono.'), q('A fase fotoquímica fornece ao ciclo de Calvin:', ['ATP e NADPH', 'Somente O₂', 'Etanol'], 0, 'ATP fornece energia e NADPH poder redutor.'), q('No ponto de compensação, a planta:', ['Parou de respirar', 'Tem saldo líquido de trocas de CO₂ igual a zero', 'Parou todas as reações'], 1, 'Fotossíntese e respiração continuam, com taxas que se compensam.')])

add('organelas-citoplasmaticas', 'Organelas citoplasmáticas', 'Biologia',
'Relacionar estruturas celulares às suas funções e acompanhar síntese, transporte, digestão e transformação de energia dentro da célula.', [
s('1. Organização celular e compartimentos', 'Citoplasma eucariótico = citosol + estruturas e organelas fora do núcleo.', 'O citosol é a porção fluida onde ocorrem numerosas reações, como a glicólise. As organelas criam ambientes especializados, com enzimas e condições próprias. Compartimentalização permite separar processos incompatíveis e coordenar etapas por transporte de moléculas e vesículas.', 'Procariontes não apresentam núcleo delimitado nem o sistema típico de organelas membranosas eucarióticas, mas possuem ribossomos, membrana e organização interna. Plantas e animais são eucariontes; não confunda parede celular com membrana plasmática. O uso do termo organela para estruturas não membranosas varia entre materiais, por isso observe a descrição funcional.'),
s('2. Ribossomos e retículo endoplasmático', 'Ribossomos: síntese de proteínas · RER: proteínas de secreção e membrana · REL: lipídios e outras funções.', 'Ribossomos são complexos de RNA ribossômico e proteínas que traduzem RNA mensageiro. Livres no citosol, produzem muitas proteínas usadas nesse compartimento e proteínas destinadas a certas organelas. Associados ao retículo endoplasmático rugoso (RER), participam da síntese de proteínas que entram na via secretora, incluindo proteínas de membrana e lisossomais.', 'O retículo endoplasmático liso (REL) participa da síntese de lipídios e, em células especializadas, de detoxificação e armazenamento de Ca²⁺. No músculo, o retículo sarcoplasmático regula cálcio na contração. RER e REL são regiões funcionalmente distintas de uma rede; não são fábricas totalmente desconectadas.'),
s('3. Complexo golgiense e rota de secreção', 'RER → vesículas → Golgi → vesículas de destino → membrana, secreção ou compartimentos internos.', 'O complexo golgiense modifica, organiza e direciona proteínas e lipídios. Seu lado cis recebe materiais da via do retículo; o lado trans participa da distribuição. Modificações em açúcares ligados a proteínas ajudam no processamento e direcionamento, mas os detalhes variam conforme a molécula.', 'Uma célula que secreta enzimas digestivas costuma ter RER e Golgi desenvolvidos. A proteína é sintetizada por ribossomos, processada no retículo e no Golgi e transportada em vesículas. Na exocitose, a membrana da vesícula se funde com a plasmática e libera o conteúdo sem a proteína atravessar a bicamada diretamente.'),
s('4. Lisossomos, peroxissomos e vacúolos', 'Lisossomo: hidrólise em meio ácido · peroxissomo: oxidações e controle de H₂O₂.', 'Lisossomos possuem enzimas que degradam materiais de endocitose e componentes celulares encaminhados por autofagia. Seu interior ácido favorece essas enzimas. Autofagia é um mecanismo de manutenção e reciclagem, não significa necessariamente morte da célula.', 'Peroxissomos realizam reações oxidativas e contêm enzimas como catalase, que decompõe H₂O₂. Não confunda com lisossomos: as reações e funções são distintas. O vacúolo central vegetal armazena substâncias, participa da degradação e mantém pressão de turgor; sua membrana é o tonoplasto.'),
s('5. Mitocôndrias e cloroplastos', 'Mitocôndria: respiração e funções metabólicas · cloroplasto: fotossíntese.', 'Mitocôndrias apresentam membranas externa e interna, cristas, matriz e espaço intermembranar. A membrana interna sustenta a cadeia respiratória e a ATP sintase; o ciclo de Krebs ocorre principalmente na matriz. A glicólise permanece no citosol. A quantidade de mitocôndrias varia com o tipo celular e a demanda metabólica.', 'Cloroplastos têm estroma e tilacoides. Contêm pigmentos fotossintéticos e ocorrem em células fotossintetizantes de plantas e algas. Nem toda célula vegetal tem cloroplastos: muitas células de raízes não os possuem. Ambas as organelas têm DNA e ribossomos próprios, evidências compatíveis com origem endossimbiótica, mas dependem também de muitos genes nucleares.'),
s('6. Citoesqueleto, centríolos e movimento', 'Microfilamentos de actina · filamentos intermediários · microtúbulos.', 'O citoesqueleto sustenta a forma, organiza o interior, permite transporte e participa da divisão. Microtúbulos, associados a proteínas motoras, organizam vias de transporte e compõem o fuso mitótico. Actina participa de movimentos e, com miosina, da contração muscular.', 'Centríolos são estruturas de microtúbulos presentes em muitas células animais e relacionadas à organização de cílios e flagelos. Não são universais nem a única forma de organizar o fuso: plantas superiores dividem-se sem centríolos típicos. Cílios e flagelos eucarióticos diferem estruturalmente dos flagelos bacterianos.'),
s('7. Como identificar a célula pela função', 'Mais síntese e secreção → mais RER/Golgi · maior demanda energética → especialização metabólica.', 'Compare função e estrutura em vez de decorar desenhos. Células secretoras de proteínas investem na via secretora; células produtoras de hormônios esteroides apresentam REL associado à síntese lipídica. Fagócitos usam sistemas endossômicos e lisossomais para degradar materiais incorporados.', 'Nem toda célula tem todas as organelas. Hemácias humanas maduras perderam núcleo e mitocôndrias, por exemplo. Diagramas são modelos: tamanhos, números e posições não devem ser tomados como fotografias universais de qualquer célula.'),
], [e('Seguir uma enzima secretada', 'Qual rota uma enzima pancreática secretada pode percorrer?', ['Ribossomos associados ao RER iniciam a síntese na via secretora.', 'A proteína é processada e transportada ao Golgi.', 'Vesículas secretoras se fundem com a membrana.'], 'RER → Golgi → vesículas → exocitose.'), e('Distinguir digestão de oxidação', 'Uma organela tem catalase e decompõe H₂O₂. Qual é?', ['Identifique a enzima e o substrato.', 'Catalase é característica dos peroxissomos.', 'Lisossomos são associados a enzimas hidrolíticas e meio ácido.'], 'Peroxissomo.')],
['Não atribua síntese de proteína ao Golgi: ele processa e direciona.', 'Não diga que toda célula vegetal tem cloroplastos.', 'Não confunda lisossomos e peroxissomos.'], [q('A tradução de proteínas ocorre nos:', ['Ribossomos', 'Lisossomos', 'Vacúolos'], 0, 'Ribossomos leem o RNA mensageiro e sintetizam polipeptídeos.'), q('Qual organela modifica e direciona proteínas da via secretora?', ['Golgi', 'Centríolo', 'Peroxissomo'], 0, 'O complexo golgiense processa e distribui materiais.'), q('O interior ácido favorece as enzimas dos:', ['Lisossomos', 'Ribossomos', 'Centríolos'], 0, 'Lisossomos contêm hidrolases ativas em ambiente ácido.'), q('A cadeia respiratória eucariótica se localiza:', ['Na membrana interna mitocondrial', 'No Golgi', 'Na parede celular'], 0, 'A membrana interna sustenta cadeia e gradiente de prótons.')])

add('permeabilidade-celular', 'Permeabilidade celular', 'Biologia',
'Entender a seletividade da membrana e prever transportes passivos, ativos, osmose e movimentação por vesículas.', [
s('1. Membrana e permeabilidade seletiva', 'Mosaico fluido: bicamada lipídica com proteínas e outros componentes.', 'Fosfolipídios têm região polar voltada para os meios aquosos e caudas apolares voltadas para o interior da bicamada. Proteínas, colesterol em células animais e carboidratos associados completam a organização. A membrana é dinâmica e assimétrica; as duas faces não são idênticas.', 'Moléculas pequenas apolares, como O₂ e CO₂, atravessam a bicamada com relativa facilidade. Íons e muitas moléculas polares exigem proteínas específicas. Tamanho, carga, solubilidade em lipídios e presença de canais ou transportadores determinam a permeabilidade; seletiva não significa absolutamente impermeável.'),
s('2. Difusão simples e facilitada', 'Transporte passivo: fluxo a favor do gradiente, sem gasto direto de energia metabólica.', 'Na difusão simples, moléculas atravessam a bicamada sem transportador. Há movimento em ambos os sentidos, com fluxo líquido a favor do gradiente. No equilíbrio, o movimento molecular continua, mas não existe fluxo líquido. Não imagine que as partículas parem.', 'Na difusão facilitada, canais ou carreadores permitem passagem de solutos. Canais iônicos podem abrir em resposta a estímulos; carreadores ligam o soluto e mudam de conformação. A disponibilidade de transportadores pode limitar a velocidade. Usar uma proteína não torna o transporte automaticamente ativo.'),
s('3. Osmose e soluções', 'Osmose: fluxo líquido de água através de membrana seletivamente permeável.', 'A água tende a fluir para o lado de menor potencial hídrico. Em um modelo simples com mesma pressão e solutos não permeantes, isso corresponde ao lado mais concentrado nesses solutos. Aquaporinas facilitam o transporte. O movimento pode ser contrabalançado por pressão, como no turgor vegetal.', 'Hipotônico, hipertônico e isotônico descrevem o efeito de uma solução sobre o volume celular e dependem especialmente dos solutos que não atravessam livremente a membrana no intervalo considerado. Igual concentração total de partículas, ou iso-osmolaridade, não garante isotonicidade se os solutos tiverem permeabilidades diferentes.'),
s('4. Células animais e vegetais na osmose', 'Meio hipotônico: entrada líquida de água · hipertônico: saída líquida de água.', 'Uma célula animal em meio muito hipotônico pode inchar e sofrer lise; em meio hipertônico, perde água e encolhe. Em meio isotônico, não há alteração sustentada de volume pelo fluxo líquido. Sempre identifique o meio de comparação e quais solutos atravessam a membrana.', 'A parede celular vegetal limita a expansão. Em meio hipotônico, a célula pode ficar túrgida e a pressão interna se opõe à entrada de água. Em meio hipertônico, a perda de água pode causar plasmólise, com retração do protoplasto em relação à parede. A parede não bloqueia por si só a passagem de água.'),
s('5. Transporte ativo primário e secundário', 'Primário: acoplado diretamente a energia, como ATP · secundário: usa gradiente previamente estabelecido.', 'Transportes ativos movem alguma espécie contra seu gradiente eletroquímico, acoplados a uma fonte de energia. A bomba de Na⁺/K⁺ usa ATP e, por ciclo, geralmente transporta 3 Na⁺ para fora e 2 K⁺ para dentro. Ela mantém gradientes importantes para volume, excitabilidade e outros transportes.', 'No cotransporte secundário, o movimento favorável de um íon pode impulsionar outro soluto contra seu gradiente. O simporte Na⁺/glicose é um exemplo. Ele não hidrolisa ATP diretamente, mas depende do gradiente sustentado por bombas. Simporte move espécies no mesmo sentido; antiporte, em sentidos opostos.'),
s('6. Endocitose, exocitose e gradiente elétrico', 'Fagocitose: partículas grandes · pinocitose: fluido · exocitose: fusão de vesículas.', 'A endocitose incorpora materiais pela deformação da membrana e formação de vesículas. Receptores podem conferir seletividade. Na fagocitose, partículas grandes são englobadas e podem ser encaminhadas para digestão. Na exocitose, a vesícula se funde com a membrana e libera seu conteúdo.', 'Para íons, considere concentração e diferença de potencial elétrico: juntos formam o gradiente eletroquímico. Um íon pode seguir sua força resultante mesmo contra a tendência da concentração isolada. Para resolver questões, identifique a substância, a proteína, o sentido e a fonte de energia.'),
], [e('Prever o volume', 'Uma hemácia é colocada em solução com maior concentração de solutos não permeantes que seu citosol. O que ocorre?', ['O meio externo é hipertônico em relação à célula.', 'Há saída líquida de água por osmose.', 'A célula diminui de volume.'], 'A hemácia encolhe.'), e('Identificar o cotransporte', 'Glicose entra contra seu gradiente junto com Na⁺ a favor do gradiente. Que transporte é esse?', ['A glicose usa a energia armazenada no gradiente de Na⁺.', 'O transportador não precisa hidrolisar ATP diretamente.', 'Como as duas espécies seguem o mesmo sentido, é simporte.'], 'Transporte ativo secundário por simporte.')],
['Não diga que toda proteína de transporte gasta ATP.', 'Não confunda osmose com movimento do sal.', 'Considere a componente elétrica nos gradientes de íons.'], [q('O₂ atravessando a bicamada a favor do gradiente exemplifica:', ['Difusão simples', 'Fagocitose', 'Transporte ativo primário'], 0, 'O₂ é pequeno e apolar e pode atravessar sem carreador.'), q('Uma célula animal em meio hipotônico tende a:', ['Perder água', 'Receber água', 'Produzir parede celular'], 1, 'No modelo com solutos não permeantes, a água entra por osmose.'), q('A bomba Na⁺/K⁺ normalmente move por ciclo:', ['3 Na⁺ para fora e 2 K⁺ para dentro', '3 Na⁺ para dentro e 2 K⁺ para fora', 'Somente água'], 0, 'Esse ciclo usa ATP e mantém gradientes iônicos.'), q('Difusão facilitada é:', ['Sempre ativa', 'Passiva, mediada por proteínas', 'Transporte por vesículas'], 1, 'O fluxo segue o gradiente eletroquímico sem acoplamento energético ativo.')])

add('glicidios', 'Glicídios', 'Biologia',
'Reconhecer carboidratos, compreender suas ligações e funções e relacionar digestão, reservas energéticas e estruturas celulares.', [
s('1. O que são glicídios?', 'Glicídios = carboidratos = sacarídeos.', 'Carboidratos incluem açúcares simples e moléculas formadas por suas unidades. São importantes como combustível, reserva, estrutura e reconhecimento celular. Muitos contêm C, H e O, mas a fórmula genérica (CH₂O)ₙ não define todos: desoxirribose e derivados nitrogenados são exemplos que exigem cuidado.', 'Não reduza carboidrato a “doce”. Amido e celulose são carboidratos, mas não têm o sabor da sacarose. Também não confunda função energética com exclusividade: lipídios e proteínas podem fornecer energia, e carboidratos podem desempenhar funções estruturais.'),
s('2. Monossacarídeos e isomeria', 'Pentoses: 5 C · hexoses: 6 C · glicose, frutose e galactose: C₆H₁₂O₆.', 'Monossacarídeos são unidades que não são hidrolisadas em carboidratos menores. Ribose participa do RNA e de nucleotídeos como ATP; desoxirribose participa do DNA. Glicose é um substrato central do metabolismo; frutose e galactose também entram em vias após transformações.', 'Ter a mesma fórmula molecular não significa ter a mesma estrutura. Glicose e frutose diferem na organização química. Em solução, muitos açúcares formam estruturas cíclicas, com configurações como alfa e beta; a orientação de uma ligação pode mudar profundamente a digestibilidade do polímero.'),
s('3. Ligações glicosídicas e dissacarídeos', 'Glicose + frutose → sacarose · glicose + galactose → lactose · glicose + glicose → maltose.', 'Uma ligação glicosídica conecta unidades de açúcar. Na representação escolar, sua formação envolve condensação, com saída de água; a hidrólise usa água para romper a ligação. Células utilizam enzimas e intermediários ativados para construir esses compostos.', 'Enzimas são específicas para determinadas ligações. Lactase hidrolisa lactose em glicose e galactose; sua baixa atividade pode levar lactose ao intestino grosso, onde microrganismos a fermentam, contribuindo para gases e efeito osmótico. Intolerância à lactose não é o mesmo que alergia às proteínas do leite.'),
s('4. Amido e glicogênio: reservas', 'Amido: reserva vegetal · glicogênio: reserva de animais e fungos.', 'Amido inclui amilose, principalmente linear com ligações alfa(1→4), e amilopectina, ramificada também com alfa(1→6). Plantas acumulam amido em estruturas como sementes e órgãos de reserva. A ligação e a organização afetam o acesso das enzimas.', 'Glicogênio é um polímero de glicose bastante ramificado, com ligações alfa(1→4) e pontos alfa(1→6). Em humanos, o fígado ajuda a manter glicose sanguínea; músculos usam seu glicogênio principalmente para suas próprias demandas. Reserva de carboidrato não é armazenada na mesma forma que reserva lipídica.'),
s('5. Celulose, quitina e reconhecimento', 'Celulose: glicose com ligações beta(1→4) · quitina: unidades de N-acetilglicosamina.', 'Celulose forma fibras resistentes na parede vegetal. Humanos não produzem celulase capaz de hidrolisar suas ligações de forma significativa; ela contribui para a fibra alimentar. Alguns animais utilizam associações com microrganismos para aproveitar materiais ricos em celulose.', 'Quitina participa do exoesqueleto de artrópodes e da parede dos fungos. Carboidratos ligados a proteínas e lipídios na face externa da membrana compõem parte do glicocálix e participam de reconhecimento e adesão. A função depende da estrutura, não apenas da quantidade de carbonos.'),
s('6. Digestão e integração metabólica', 'Polissacarídeos → fragmentos menores → monossacarídeos absorvíveis.', 'Amilases atuam sobre certas ligações do amido; enzimas da superfície intestinal completam a digestão de vários carboidratos. Monossacarídeos são absorvidos por mecanismos específicos, incluindo transportadores. O corpo não absorve normalmente uma molécula de amido inteira para depois digeri-la no sangue.', 'Glicose pode alimentar glicólise, ser armazenada em glicogênio ou contribuir para outras sínteses conforme o estado metabólico. Em provas, associe monômero, ligação, organismo, função e enzima. Duas cadeias feitas de glicose, como amido e celulose, podem ter propriedades muito diferentes.'),
], [e('Mesmos monômeros, funções distintas', 'Por que digerimos amido, mas não celulose de modo equivalente?', ['Ambos são polímeros de glicose.', 'As ligações e a organização espacial diferem.', 'Nossas enzimas digestivas atuam sobre ligações do amido, mas não temos celulase própria.'], 'A especificidade enzimática depende do tipo de ligação.'), e('Hidrólise de dissacarídeo', 'Quais produtos resultam da hidrólise da lactose?', ['Identifique as unidades que compõem a lactose.', 'A lactase promove ruptura da ligação com participação de água.', 'As unidades liberadas são monossacarídeos diferentes.'], 'Glicose e galactose.')],
['Não classifique todo glicídio como açúcar doce.', 'Não confunda intolerância à lactose com alergia ao leite.', 'Não suponha que polímeros de glicose tenham sempre a mesma função.'], [q('A reserva de carboidrato típica de animais é:', ['Glicogênio', 'Celulose', 'Quitina'], 0, 'Glicogênio armazena glicose, especialmente em fígado e músculos humanos.'), q('O açúcar do RNA é:', ['Desoxirribose', 'Ribose', 'Sacarose'], 1, 'A ribose é uma pentose presente no RNA.'), q('Sacarose é formada por:', ['Glicose e frutose', 'Glicose e galactose', 'Duas galactoses'], 0, 'Esse dissacarídeo reúne glicose e frutose.'), q('A celulose tem função principalmente:', ['Estrutural na parede vegetal', 'De enzima digestiva', 'De hormônio esteroide'], 0, 'As fibras de celulose contribuem para a resistência da parede.')])

add('lipidios', 'Lipídios', 'Biologia',
'Compreender a diversidade dos lipídios e relacionar estrutura a reserva energética, membranas, sinalização e digestão.', [
s('1. Um grupo diverso de moléculas', 'Lipídios têm baixa solubilidade em água; alguns apresentam regiões polares e apolares.', 'Lipídios não formam uma única família de polímeros com um monômero universal. Triacilgliceróis, fosfolipídios, esteroides e ceras têm estruturas diferentes. Sua característica geral está no comportamento frente a solventes e na presença de regiões predominantemente apolares.', 'As funções incluem reserva energética, isolamento térmico, proteção, formação de membranas, sinalização e impermeabilização. Gorduras não são apenas combustível: a estrutura de membranas e a produção de vários hormônios dependem de moléculas lipídicas.'),
s('2. Ácidos graxos e insaturações', 'Saturado: sem C=C na cadeia · insaturado: uma ou mais ligações C=C.', 'Um ácido graxo tem uma cadeia hidrocarbonada e um grupo carboxila. Cadeias maiores costumam intensificar interações de dispersão. Nos saturados, as cadeias podem se aproximar mais; duplas cis introduzem dobras que dificultam empacotamento e frequentemente reduzem a temperatura de fusão em comparações adequadas.', 'Duplas trans mantêm geometria mais linear que cis e podem favorecer maior empacotamento. Não confunda gordura vegetal com automaticamente insaturada ou líquida: há exceções, como óleos ricos em saturados. As propriedades dependem da mistura, do tamanho das cadeias e das posições e configurações das duplas.'),
s('3. Triacilgliceróis e reserva energética', 'Triacilglicerol = glicerol esterificado com três ácidos graxos.', 'A ligação éster conecta ácidos graxos ao glicerol. Triacilgliceróis são armazenados em gotículas lipídicas e oferecem reserva concentrada. Em estimativas alimentares, lipídios fornecem cerca de 9 kcal/g, enquanto carboidratos e proteínas fornecem cerca de 4 kcal/g; são médias de aproveitamento energético.', 'A natureza pouco polar permite armazenar triacilgliceróis com pouca água associada, diferentemente do glicogênio. Na mobilização, lipases liberam ácidos graxos e glicerol. Não confunda a gordura armazenada com as moléculas fosfolipídicas que organizam a membrana.'),
s('4. Fosfolipídios e organização de membranas', 'Anfipático: região hidrofílica + região hidrofóbica.', 'Muitos fosfolipídios apresentam cabeça polar e duas caudas apolares. Em água, a associação em bicamadas mantém as caudas protegidas do contato direto com o meio aquoso. Isso cria uma barreira seletiva que interage com proteínas e outros componentes, sem constituir uma parede rígida.', 'Cadeias mais insaturadas, mantendo outras condições comparáveis, costumam aumentar a fluidez por dificultar empacotamento. Temperatura e colesterol também influenciam a membrana. Colesterol limita movimentos em algumas condições e impede empacotamento excessivo em outras: seu efeito não cabe em “sempre aumenta” ou “sempre diminui” a fluidez.'),
s('5. Esteroides, ceras e moléculas essenciais', 'Colesterol: componente de membranas e precursor de hormônios esteroides, ácidos biliares e vitamina D.', 'Esteroides possuem um esqueleto de anéis fusionados, diferente da estrutura de triacilgliceróis. Colesterol não é um tipo de proteína nem sinônimo de gordura acumulada. LDL e HDL são partículas lipoproteicas que transportam lipídios no sangue; não são duas espécies químicas diferentes de colesterol.', 'Ceras podem atuar na impermeabilização de superfícies. Alguns ácidos graxos precisam ser obtidos na alimentação: em humanos, ácido linoleico e alfa-linolênico são essenciais e precursores de outras moléculas. “Essencial” indica limitação de síntese pelo organismo, não que os demais não tenham importância.'),
s('6. Digestão, absorção e transporte', 'Bile emulsifica · lipases hidrolisam · lipoproteínas transportam.', 'Sais biliares ajudam a dispersar gotículas de gordura, aumentando a superfície disponível para enzimas; bile não é uma enzima. Lipases quebram ligações dos lipídios. Produtos da digestão se associam a estruturas como micelas, que facilitam sua aproximação da superfície intestinal.', 'Após a absorção de muitos lipídios, enterócitos reconstroem triacilgliceróis e os organizam em quilomícrons para transporte. Ácidos graxos de diferentes tamanhos podem seguir rotas distintas. Em provas, separe emulsificação física, hidrólise enzimática, absorção e transporte; são etapas complementares.'),
], [e('Calcular energia alimentar', 'Usando 9 kcal/g, qual energia corresponde a 8 g de lipídios?', ['Identifique o fator fornecido: 9 kcal por grama.', 'Multiplique 8 g × 9 kcal/g.', 'A unidade g se cancela.'], '72 kcal nessa estimativa.'), e('Explicar a fluidez', 'Duas membranas diferem apenas pela maior proporção de duplas cis em uma delas. Qual tende a ser mais fluida?', ['Duplas cis introduzem dobras nas caudas.', 'As dobras dificultam o empacotamento próximo.', 'Com demais condições iguais, isso favorece maior fluidez.'], 'A membrana mais rica em cadeias insaturadas cis.')],
['Não diga que todos os lipídios são polímeros de ácidos graxos.', 'Não confunda bile com lipase.', 'Não trate LDL e HDL como moléculas diferentes de colesterol.'], [q('Triacilglicerol é composto por:', ['Glicerol e três ácidos graxos', 'Três aminoácidos', 'Glicose e frutose'], 0, 'Os ácidos graxos se ligam ao glicerol por ligações éster.'), q('Uma molécula anfipática tem:', ['Somente regiões apolares', 'Regiões hidrofílica e hidrofóbica', 'Obrigatoriamente DNA'], 1, 'Essa dualidade explica a organização dos fosfolipídios em água.'), q('O papel dos sais biliares na digestão é:', ['Emulsificar lipídios', 'Produzir glicose diretamente', 'Ser a enzima lipase'], 0, 'A emulsificação aumenta a área de contato para ação enzimática.'), q('Uma função do colesterol é:', ['Participar de membranas e servir de precursor de esteroides', 'Traduzir RNA mensageiro', 'Formar celulose'], 0, 'Ele tem funções estruturais e é precursor de diversas moléculas.')])

add('enzimas', 'Enzimas', 'Biologia',
'Entender catálise e especificidade enzimática e interpretar efeitos de temperatura, pH, substrato, inibidores e regulação metabólica.', [
s('1. Catalisadores biológicos e energia de ativação', 'Enzimas diminuem a energia de ativação sem alterar ΔG nem a posição do equilíbrio.', 'A maioria das enzimas é proteica, mas existem RNAs catalíticos, chamados ribozimas. Elas aceleram reações por um caminho de menor barreira energética. Não fornecem energia livre que transforme uma reação desfavorável em favorável por si só; nas células, reações podem ser acopladas a processos como hidrólise de ATP.', 'Uma enzima é regenerada ao final do ciclo catalítico, embora possa ser danificada ou degradada ao longo do tempo. Ela acelera a aproximação do equilíbrio sem mudar a constante de equilíbrio. Não confunda velocidade, que é uma questão cinética, com favorabilidade energética.'),
s('2. Sítio ativo e especificidade', 'E + S ⇌ ES → E + P.', 'O substrato interage com uma região chamada sítio ativo. Forma, cargas e interações químicas favorecem certos substratos e reações. O complexo enzima-substrato permite orientar reagentes e estabilizar estados de transição. Especificidade não exige que uma enzima aceite uma única molécula em qualquer caso; algumas atuam sobre uma família de substratos.', 'O modelo de ajuste induzido reconhece mudanças de conformação durante a interação. A imagem chave-fechadura ajuda a iniciar o estudo, mas não representa toda a flexibilidade molecular. Alterar a estrutura tridimensional pode comprometer a catálise mesmo que a sequência de aminoácidos continue intacta.'),
s('3. Temperatura e pH', 'A atividade depende de condições que preservem estrutura e interações do sítio ativo.', 'Elevar a temperatura pode aumentar a velocidade dentro de uma faixa, mas temperaturas altas podem desnaturar a proteína e reduzir a atividade. Resfriamento geralmente diminui a velocidade sem provocar a mesma desnaturação irreversível; o efeito depende da enzima e das condições.', 'O pH modifica a ionização de grupos do substrato e da enzima e pode alterar interações e estrutura. Pepsina atua bem em meio ácido; várias enzimas intestinais atuam em faixas menos ácidas ou alcalinas. Não há pH ou temperatura ótima universal, e curvas experimentais precisam ser lidas nas condições apresentadas.'),
s('4. Concentração de substrato e saturação', 'Modelo de Michaelis–Menten: v = Vmax[S]/(Km + [S]).', 'Com quantidade fixa de enzima, aumentar substrato pode elevar a velocidade inicial até a aproximação de um máximo, quando muitos sítios estão ocupados. Nessa faixa, adicionar mais substrato já não aumenta muito a velocidade. Aumentar a quantidade de enzima ativa, com substrato suficiente, pode elevar Vmax.', 'No modelo simples, Km é a concentração de substrato em que v = Vmax/2. Ele não é uma medida universal e direta de afinidade em todo mecanismo. Enzimas alostéricas podem ter curvas sigmoides e não seguir esse modelo. Antes de usar a fórmula, identifique a hipótese do exercício.'),
s('5. Inibição competitiva e outros mecanismos', 'Competitiva simples: Km aparente aumenta; Vmax se mantém.', 'Na inibição competitiva reversível simples, substrato e inibidor competem por formas mutuamente exclusivas de ligação. Aumentar substrato pode reduzir o efeito relativo do inibidor. No modelo clássico, exige-se mais substrato para atingir metade da velocidade máxima, mas Vmax permanece a mesma.', 'Na inibição não competitiva pura, Vmax diminui e Km se mantém; é um caso específico da inibição mista, não sinônimo de qualquer inibidor que se liga fora do sítio ativo. Inibidores irreversíveis podem inativar enzimas de forma duradoura. Diferencie o mecanismo pela evidência, não apenas pelo local de ligação.'),
s('6. Cofatores, coenzimas e regulação', 'Cofator: componente auxiliar não proteico · coenzima: cofator orgânico.', 'Íons metálicos e moléculas orgânicas podem ser necessários à atividade. NAD⁺ e FAD participam de transferências de elétrons; muitas coenzimas derivam de vitaminas. A proteína sem o componente necessário pode ser chamada apoenzima; o conjunto funcional, holoenzima.', 'A célula regula vias por alterações alostéricas, modificações covalentes, quantidade de enzima e disponibilidade de substratos. No feedback negativo, um produto final pode reduzir a atividade de uma etapa anterior, evitando produção desnecessária. O regulador pode se ligar a um sítio diferente do ativo e alterar a conformação.'),
s('7. Como interpretar gráficos e experimentos', 'Compare uma variável de cada vez: velocidade inicial, [S], temperatura, pH ou inibidor.', 'Leia eixos e unidades. Uma curva de produto ao longo do tempo pode desacelerar por consumo de substrato ou acúmulo de produto; isso não prova desnaturação. Já um gráfico de velocidade inicial em função de substrato estuda outro tipo de relação.', 'Use um controle e mantenha condições comparáveis. Se uma amostra aquecida perde atividade após resfriar, a alteração pode indicar dano estrutural nas condições do ensaio. A conclusão precisa ser compatível com o que foi medido, evitando extrapolar um experimento para todas as enzimas.'),
], [e('Usar Km', 'Uma enzima segue Michaelis–Menten, com Vmax = 100 unidades e [S] = Km. Qual é v?', ['Substitua [S] por Km: v = 100 Km/(Km + Km).', 'O denominador fica 2 Km.', 'Cancele Km: v = 100/2.'], '50 unidades de velocidade.'), e('Reconhecer saturação', 'Dobrar o substrato quase não altera a velocidade, mas dobrar a enzima ativa a aumenta. Como interpretar?', ['Os sítios ativos já estavam amplamente ocupados.', 'Mais substrato oferece pouco ganho perto da saturação.', 'Mais enzima fornece mais sítios catalíticos, com substrato suficiente.'], 'O ensaio inicial estava próximo de Vmax para aquela quantidade de enzima.')],
['Não afirme que enzimas mudam o equilíbrio da reação.', 'Não considere toda enzima uma proteína: há ribozimas.', 'Não interprete qualquer queda de velocidade como desnaturação.', 'Não generalize inibição não competitiva pura para toda regulação alostérica.'], [q('Uma enzima acelera a reação porque:', ['Reduz a energia de ativação', 'Aumenta obrigatoriamente ΔG', 'Muda a constante de equilíbrio'], 0, 'Ela oferece um caminho catalítico com menor barreira de ativação.'), q('No modelo Michaelis–Menten, quando [S] = Km:', ['v = Vmax', 'v = Vmax/2', 'v = 0'], 1, 'Substituindo na equação, o denominador é 2 Km.'), q('Um cofator orgânico é chamado de:', ['Coenzima', 'Celulose', 'Fosfolipídio obrigatório'], 0, 'Coenzimas são componentes orgânicos auxiliares da catálise.'), q('Na inibição competitiva simples reversível:', ['Vmax aumenta sempre', 'Mais substrato pode reduzir o efeito relativo do inibidor', 'A enzima é necessariamente destruída'], 1, 'Substrato e inibidor competem; Vmax permanece igual no modelo clássico.')])

